SELECT sil.id AS id, sil.approve_status AS approveStatus, sil.approve_user_id AS approveUserId, sil.approve_user_name AS approveUserName, sil.approve_time AS approveTime, sil.invalid_status AS invalidStatus, sil.invalid_remark AS invalidRemark, sil.invalid_time AS invalidTime, sil.code AS code, sil.user_id AS userId, sil.user_name AS userName, sil.dept_id AS deptId, sil.dept_name AS deptName, sil.bill_date AS billDate, sil.create_time AS createTime, sil.create_user_name AS createUserName, sild.sku_no AS skuNo, sild.sku_id AS skuId, sild.product_name AS productName, sild.qty AS qty FROM sample_initial_ledger sil LEFT JOIN sample_initial_ledger_detail sild ON sil.id = sild.main_id AND sild.is_deleted = false WHERE ${params.sqlMap.default} AND sil.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sil.create_time DESC, sil.id ASC

SELECT sil.id AS id, sil.approve_status AS approveStatus, sil.approve_user_id AS approveUserId, sil.approve_user_name AS approveUserName, sil.approve_time AS approveTime, sil.invalid_status AS invalidStatus, sil.invalid_remark AS invalidRemark, sil.invalid_time AS invalidTime, sil.code AS code, sil.user_id AS userId, sil.user_name AS userName, sil.dept_id AS deptId, sil.dept_name AS deptName, sil.bill_date AS billDate, sil.create_time AS createTime, sil.create_user_name AS createUserName, sild.sku_no AS skuNo, sild.sku_id AS skuId, sild.product_name AS productName, sild.qty AS qty FROM sample_initial_ledger sil LEFT JOIN sample_initial_ledger_detail sild ON sil.id = sild.main_id AND sild.is_deleted = false WHERE ${params.sqlMap.default} AND sil.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sil.create_time DESC, sil.id ASC

SELECT approve_status AS tabFlag, count(*) AS count FROM sample_initial_ledger WHERE is_deleted=FALSE
${params.permissionSql}
GROUP BY approve_status
